    chipRainPerYear: 'mm yemvula / unyaka',
    summaryWarmWetSummer: 'Ehlobo kushisa futhi kunezimvula, ebusika kufudumele futhi komile njalo kukhona inkungu ekuseni. Imvula yasehlobo ethembekile nesikhathi eside esingeqhwa ivumela ukulima unyaka wonke — hlela ngesikhathi esomile ebusika neziphepho zasantambama ehlobo.',
    summaryReliableRainfall: 'Imvula ithembekile unyaka wonke ngezinga elifanele futhi akukho sikhathi eside esomile. Kuhle ukukhiqiza izilimo ezahlukene ngokuqhubekayo — qaphela ubunzima bomswakama nezinhlupho zezilimo ngaphezu kobushisa.',
    summaryWetMildWinter: 'Ebusika kunezimvula futhi kufudumele, ehlobo kushisa futhi komile. Isikhathi semvula yasebusika esibandayo yisikhathi sakho esibalulekile sokuhlanyela; ehlobo kudingeka izilimo ezimelana nokuwasha noma eziselwa amanzi.',
    summarySemiAridSteppe: 'Insimu ye-steppe engenamvula ngokwanele — imvula ephakathi nobunzima bokuguquguquka kwesikhathi. Ukuqoqa amanzi nokusebenzisa imilindi kubalulekile ukwandisa isikhathi sokukhula.',
    summaryAridDesert: 'Ihlane elingenamvula — imvula incane futhi ayithembekile. Ukuqoqa amanzi kumelwe kuqalwe ngaphambi kokuthoma ukukhiqiza ukudla ngokuphelele.',
    summaryHighAltitude: 'Indawo ephakeme enebusika obuqandayo nesikhathi esifushane sokukhula. Sebenzisa izindawo ezincane ezivelele ilanga futhi usebenzise izinhlobo ezimelana neqhwa.',
