    chipRainPerYear: 'mm yemvula / unyaka',
    summaryWarmWetSummer: 'Ehlotyeni kushushu kwaye kunezimvula, ebusika kufudumele kwaye komile rhoqo kungenkungu ekuseni. Imvula ehlotyeni ethembekileyo nexesha elide elingenasikhephe sivumela ukulima unyaka wonke — ceba ixesha eliomileyo ebusika neziphepho zemva kwemini ehlotyeni.',
    summaryReliableRainfall: 'Imvula ithembekile unyaka wonke kwelinye amazinga kwaye akukho xesha elide eliomileyo. Kulungile ukuqhubeka neentlobo ezahlukeneyo zezilimo — jonga ubunzima bomswakama nezifo zezilimo ngaphezu kokuba nengxaki yushushu.',
    summaryWetMildWinter: 'Ebusika kunezimvula kwaye kufudumele, ehlotyeni kushushu kwaye komile. Ixesha lemvula ebusika ebandayo lixesha lakho elibalulekileyo lokuhlwayela; ehlotyeni kufuneka izilimo ezikwazi ukumelana nomxinwa wamanzi okanye ezincedwa ngamanzi.',
    summarySemiAridSteppe: 'Intsimi ye-steppe engenazimvula ngokwaneleyo — imvula ephakathi kunye nomahluko omkhulu wexesha. Ukuqoqa amanzi nokusebenzisa iindlela zokugcina amanzi zibalulekile ukunabisa ixesha lokukhula.',
    summaryAridDesert: 'Intlango eomileyo — imvula incinci kwaye ayithembekanga. Ukuqoqa amanzi kufuneka kwenziwe ngaphambi kokuba kuqalwe ukunyusa ukuvelisa ukutya.',
    summaryHighAltitude: 'Indawo ephezulu enebusika ebandayo nexesha elifutshane lokukhula. Sebenzisa iindawo ezincinci ezibheke entshonalanga yelanga kwaye usebenzise iintlobo ezikwazi ukumelana nesikhephe.',
