    chipRainPerYear: 'mm ya pula / selemo',
    summaryWarmWetSummer: 'Selemo ke sa mocheso o nang le pula, mariha ke a chesang e omileng, hangata ho na le mosi hoseng. Pula ya selemo e tshepahalang le nako e telele e senang serame e re lumella ho lema ka kakaretso ya selemo — bea molapo ho nako e omileng ya mariha le lisetlhaboelo tsa letsatsi la mantsiboa selemong.',
    summaryReliableRainfall: 'Pula e tshepahala selemo sohle ka maemo a maleba mme ha ho nako e telele e omileng. Ho loketse ho tswela pele ka lijalo tse fapaneng — ela hloko komelelo ya pula le mafu a lijalo ho feta bothata ba mocheso.',
    summaryWetMildWinter: 'Mariha ke a nang le pula le chesang, selemo ke sa mocheso o omileng. Nako ya pula ya mariha e tsidilang ke fenestere ea hao ea bohlokwa ea ho lema; selemong ho hlokahala lijalo tse kananang le komelelo kapa tse noswang.',
    summarySemiAridSteppe: 'Naga ya steppe e se nang pula ka lekana — pula ya bohareng le phapano e matla ya nako. Ho bokella metsi le ho sebedisa ditshipi ho bohlokwa ho atolosa nako ya ho mela.',
    summaryAridDesert: 'Matla a mafatšhe a omileng — pula ke nyenyane le e sa tshepahaleng. Ho bokella metsi ho lokela ho etsoa pele ho qala ho lema dijo.',
    summaryHighAltitude: 'Sebaka se holimo se nang le mariha a tsidilang le nako e khuts\'wane ya ho mela. Sebedisa libaka tse nyane tse lebisang leboea le mefuta e kananang le serame.',
