    chipRainPerYear: 'mm ya pula / ngwaga',
    summaryWarmWetSummer: 'Selemo ke sa bothitho se nago le pula, marega ke a mofutho a omilego, kgafetša go na le boruru mo mesong. Pula ya selemo ye e tshephegago le nako ye telele ye e senago serame e re letlelela go bjala go feta ngwaga — beakanya nako ya komelelo ya marega le mehlagase ya mantšiboa selelong.',
    summaryReliableRainfall: 'Pula e tshephegelaela mo ngwageng woohle ka maemo a maleba mme ga go na nako ye telele ya komelelo. Go lokile go tsweletša dimela tše dibontšhi — ela hloko komelelo ya pula le malwetše a dimela go feta mathata a mogote.',
    summaryWetMildWinter: 'Marega ke a pula a mofutho, selemo ke sa bothitho se omilego. Nako ya pula ya marega ye tsididi ke window ya gago ya bohlokwa ya go bjala; selemo go nyakaleg dimela tše di dulago le komelelo goba tše di noswago.',
    summarySemiAridSteppe: 'Naga ya steppe ye e senago pula ka mo go lekanego — pula ya magareng le phapantšho ye kgolo ya nako. Go boloka meetse le go šomiša merako go bohlokwa go oketša nako ya go mela.',
    summaryAridDesert: 'Mafelo a a omilego thata — pula ke nyenyane le ye e sa tshephegego. Go boloka meetse go swanetše go dirwa pele go ka thomišwa go bjala dijo.',
    summaryHighAltitude: 'Lefelo le le godimo le nago le marega a tsididi le nako ye khutšwane ya go mela. Šomiša dibaka tše dinyane tše di lebeletsago leboea le mefuta ye e kgonago go šiema le serame.',
