    chipRainPerYear: 'mm ya pula / ngwaga',
    summaryWarmWetSummer: 'Selemo ke bothitho le nang le pula, mariha ke mofuthu le omileng ka metlha go na le furo mo mesong. Pula ya selemo e e ntshekang le nako e telele e e senang serame e re letlelela go jala mo godimo ga ngwaga — reromela nako e omileng ya mariha le megalawatle ya motshegare mo selelong.',
    summaryReliableRainfall: 'Pula e ntsheka mo nakong yotlhe ya ngwaga ka maemo a a siameng mme ga go na nako e telele e omileng. Go siame go tsweletsa dimela tse di farologaneng — ela tlhoko tamolao ya pula le malwetse a dijalo go feta ke go tlhapisega ke kgogomalo.',
    summaryWetMildWinter: 'Mariha ke a pula le a mofuthu, selemo ke a bothitho le a omileng. Nako ya pula ya mariha e tsididi ke window ya gago ya bohlokwa ya go jala; selemo go batlegang dimela tse di dirisang kgogomalo kgotsa tse di noswang.',
    summarySemiAridSteppe: 'Naga ya steppe e e se nang pula — pula ya gare-gare le kgaogano e e nonofileng ya nako. Go buela metsi le go dirisa ditshipi di bohlokwa go golola nako ya go mela.',
    summaryAridDesert: 'Mafelo a a omileng thata — pula e nyenye le e sa ntshekang. Go buela metsi go tshwanetse go dirwa pele go ka diriwa ka go thoma go jala dijo.',
    summaryHighAltitude: 'Lefelo le le kwa godimo le nang le mariha a tsididi le nako e khutshwane ya go mela. Dirisa mafelo a mannyane a a lebisang kwa borwa le mefuta e e kgonang go phethela serame.',
