    zoneAlpineMontane: 'Ntango ya tintshava',
    chipRainPerYear: 'mm ya mpfula / lembe',
    summaryWarmWetSummer: 'Nhloboyi yi tshisa naswona yi na mpfula, xirhanguri xi phola naswona xi omile, ku na mhunguti enkarhini wa matateni. Mpfula ya nhloboyi leyi tshembhekilaka na nkarhi mule lowu pfumalaka ku helela ka xirhanguri swi lava ku tsarhiwa mimela vu-nyaka hinkwawu — endlela plani xa nkarhi wo oma wa xirhanguri na zimphunga za ntambama nhloboyi.',
    summaryReliableRainfall: 'Mpfula yi tshembheka vu-nyaka hinkwawu na vuximunhana byo faneleka naswona ku hava nkarhi mule wo oma. Swi lava ku tlhava minhlampfi mingi hi ku ya emahlweni — languta vusweti bya mpfula na timbetwa ta timhandzu emahlweni ka nxangu wa xombexi.',
    summaryWetMildWinter: 'Xirhanguri xi na mpfula naswona xi phola, nhloboyi yi tshisa naswona yi oma. Nkarhi wa mpfula ya xirhanguri yo tshila i swa nkarhi wa ku tsarhiwa mimela loku kulu; nhloboyi yi lava timhandzu leti xiximaka xombexi kumbe leti xisiwaka.',
    summarySemiAridSteppe: 'Nyika ya stephe leyi pfumalaka mpfula — mpfula ya xikongomelo na ku tshika loku kulu ka nkarhi. Ku hlengeleta mati na ku tirhisa swixelelo swi rhangeriwa ku yelelela nkarhi wa ku mela.',
    summaryAridDesert: 'Hahlamarhi ra ku pfumala mati — mpfula yo olova naswona leyi nga tshembhekiki. Ku hlengeleta mati ku fanele ku endliwa emahlweni ka ku tsarhiwa swakudya swi tano tirha.',
    summaryHighAltitude: 'Xifundzankulu lexi hanyisekaka na xirhanguri xo titima na nkarhi mutsongo wa ku mela. Tirhisa tindzhawu tincunyana leti vangamaka dzuwa naswona u tirhise minhlobo leyi tshembhelaka xirhanguri.',
