    insightSemiArid: 'Fhethu fhu si na mvua ngaho — {mm} mm/yr. U kuvhanganya mvua zwi fanela u bva phanḓa ha u dzhia miṱi ya zwiḽiwa.',
    insightModerateRain: '{mm} mm/yr — mvua ya vhukati. Mulch na maswale zwi andisa tshifhinga tshi re na mushumo tsha u mela zwavhudi.',
    insightStrongRain: '{mm} mm/yr — mvua i nambiwa. Ṱha soil-carbon u dzudzanya vhudzivhazwino kha ṅwedzi dzo omaho.',
    insightFrostExpected: 'Thubu i lavhelwa ({tempC}°C ukadamelo u re fhasi wa ḓanga). Thusa zwiṱaḓa zwi ṱhonifhaho Aug–Sep nga zwikhurumelo na fhethu huna muya we ha ṱuwa nṱha.',
    insightLightFrost: 'Vhuṱungu ha thubu tshiṱuku ({tempC}°C ukadamelo u re fhasi wa ḓanga). Ṱhoma miṱi ine ya tsha tsini na tshibolong kha mabina ane a phahama kana maramba a ṱuwa nṱha.',
    insightFrostFree: 'Hu si na thubu ṅwaha woṱhe ({tempC}°C u re fhasi). Miṱi ya zwiḽiwa ya tropiki i shuma zwavhudi fhano.',
    insightHighWind: 'Phepho khulwane yo livhana ({kmh} km/h gama). Zwikhuselo zwa phepho kha tshikhala tsha {dir} ndi tshifhinga tsha vhuimo vhu re nṱha tsha u ṱangana nazwo.',
    insightModerateWind: 'Phepho ya vhukati i bva kha {dir}. Muṱa u thihi wa muthihi kha tshikhala tsha phepho u fhungudza khatello ya zwiṱaḓa zwavhudi.',
    insightLowSoilCarbon: 'Khabone tshifhulufhelu ya mavu ({oc}%). Khompose, ntevhe ya krale na mahlwathi a nṱha zwi ḓo phindulula mvelelo yaṋu kha maḓuvha mavhili.',
    insightGoodSoilCarbon: 'Khabone yo luga ya mavu ({oc}%). Dzudzanya nga khompose na u lima tshiṱuku u dzudzanya zwivhiliwaho.',
    climateRainfallInsight: 'Mvua yo anda i na {wet}. Kuvhanganya mvua ya sithofamu u khwathisa tshifhinga tsho omaho tsha {dry}.',
