    zoneAlpineMontane: 'Vhupo ha pfura dza thavha',
    chipRainPerYear: 'mm ya mvula / nwaha',
    summaryWarmWetSummer: 'Ḓiseba ḽi a fhisa na mvula, maḓirani ho vhila na mvula isi na ya ho ṱhahiwa, gule dza mangwanani na humo ḽi divhea. Mvula ya ḓiseba ya u tenda na tshifhinga tshilapfu tshi sa vhi na ḓakhiwa i tenda uri u rima mwaha woṱhe — dzhia ngudo maḓirani o omaho na maḓuvha a mvula ya ḓiseba.',
    summaryReliableRainfall: 'Mvula ya u tenda mwaha woṱhe vhuimo vhu fanaho na hu si na tshifhinga tshilapfu tsho omaho. Zwi fanela uri u bvele phanḓa na zwilimo zwi tshio — sedzela mvula na malwadze a zwilimo phanḓa ha nḓowelo.',
    summaryWetMildWinter: 'Maḓirani o vhila na mvula na u vhila ho vhila, ḓiseba ḽa u fhisa na u oma. Tshifhinga tsha mvula ya maḓirani tsho tshifha ndi tshifhinga tshavho tshihulwane tsha u rima; ḓiseba zwilimo zwi re na u tenda maḓakwa kana zwi rotosedzhwaho.',
    summarySemiAridSteppe: 'Stephe ḽa u kanganedza mvula — mvula ya vhukati ya u khwinifhadzea tshifhinga tsha nḓowelo. U kuvhanganya mvula na u shumisa uḽi hu na ndeme uri u engedze tshifhinga tsha u mela.',
    summaryAridDesert: 'Ḓaka ḽo omaho — mvula dzi si gathi na dzi sa tendi. U kuvhanganya mvula hu fanela u dzhenisiwa phanḓa ha uri u rima zwakudya zwi kone u bvela phanḓa.',
    summaryHighAltitude: 'Fhethu ha nṱha vhune ha vha na maḓirani o ṱhahaho na tshifhinga tshifupi tsha u mela. Shumisa mivhundu mihulwane ya maḓuvha a vhuswa na mifuta ya zwilimo yo tenda u ḓikhethela maḓakwa.',
