    chipRainPerYear: 'mm lemvula / umnyaka',
    summaryWarmWetSummer: 'Ehlobo kushisa futhi kunenkhuli, ebusika kufutfuma futhi komile njalo kukhona inkhungu ekuseni. Imvula yehlobo lethembekile nesizini eside lesingenasilungelo sabanikati sikhululekile sivumela kuhlanyela iminyaka yonke — hlela ngesikhathi esomile ebusika netiphepho temtfunti ehlobo.',
    summaryReliableRainfall: 'Imvula ithembekile iminyaka yonke ngalokufanele futhi akukho sikhathi eside lesomile. Kuhle ukukhiqita tsilimo letinyenti ngekuqhubeka — phatha inkhuli kanye netinhlupho tetilwane endluzuleni kunato sikhathi sekushisa.',
    summaryWetMildWinter: 'Ebusika kunenkhuli futhi kufutfuma, ehlobo kushisa futhi komile. Isizini yemvula lebandako ngesisikhathi sakho lesibalulekile sekuhlanyela; ehlobo kudvingeka tsilimo letimelana nekushisa nome letisiwa emanti.',
    summarySemiAridSteppe: 'Isteppe lesingenakhuli — imvula lephakathi nokuguquguquka kwesikhathi lokubalulekile. Kuqoqa emanti nokusebentisa ukukhukhumala kubalulekile ukwandisa isikhathi sekukhula.',
    summaryAridDesert: 'Ihlane lelingenakhuli — imvula lencane futhi lengaqinisekiwe. Kuqoqa emanti kumele kusungulwe ngaphambi kwekutsi ukukhiqita kudla kuqhubeke.',
    summaryHighAltitude: 'Indzawo lephakeme lenebusika lobandza nesikhathi lesifushane sekukhula. Sebentisa tindawo letincane letigudla entfuntini futhi usebentise tinhlobo letimelana neliqhwa.',
