    chipRainPerYear: 'mm yemvula / unyaka',
    summaryWarmWetSummer: 'Ehlobo kushisa futhi kunezimvula, ebusika kufudumele futhi komile njalo kukhona inkungu ekuseni. Imvula yasehlobo ethembekile nesizini eside esingeqhwa akuvumeli ukuhlanyela unyaka wonke — hlela ngokwesikhathi esomile ebusika neziphepho zantambama ehlobo.',
    summaryReliableRainfall: 'Imvula ithembekile unyaka wonke ngezinga eliphakathi futhi akukho sikhathi eside esomile. Kuhle ukukhiqiza izitshalo eziningi ngokuqhubekayo — phatha umswakama kanye nezinhlupho zezilwane endluzula kunokusiza ngokushisa.',
    summaryWetMildWinter: 'Ebusika kunezimvula futhi kufudumele, ehlobo kushisa futhi komile. Isizini yomvula ebandayo yisikhathi sakho esibalulekile sokuhlanyela; ehlobo kudingeka izilimo ezimelana nokushisa noma eziselwa amanzi.',
    summarySemiAridSteppe: 'Isiteppe esinomswakama omncane — imvula ephakathi ngokuguquka kwezikhathi ezibalulekile. Ukuqoqa amanzi nokusebenzisa ukukhukhumala kubalulekile ukwandisa isikhathi sokukhula.',
    summaryAridDesert: 'Ihlane elingenamanzi — imvula encane futhi engaqinisekiwe. Ukuqoqa amanzi kumelwe kusungulwe ngaphambi kokuba ukukhiqiza ukudla kuqhubeke.',
    summaryHighAltitude: 'Indawo ephakeme enamakhaza ebusika nesikhathi esifushane sokukhula. Sebenzisa amazinga amancane aphendukela ngasenshiyanele futhi usebenzise izinhlobo ezimelana nequbulo.',
